import{_ as a,o as d,c as e,O as s}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"异步与消息架构","description":"异步与消息架构：什么时候该异步、四种消息模型、中间件选型、可靠性的三件事、事务消息与本地消息表、延迟消息与积压处理。","frontmatter":{"description":"异步与消息架构：什么时候该异步、四种消息模型、中间件选型、可靠性的三件事、事务消息与本地消息表、延迟消息与积压处理。","tags":["系统设计","消息队列","高并发","架构设计"]},"headers":[],"relativePath":"backend/系统设计/异步与消息架构.md","filePath":"backend/系统设计/异步与消息架构.md","lastUpdated":1793245104000}'),r={name:"backend/系统设计/异步与消息架构.md"};function n(o,t,l,i,p,c){return d(),e("div",null,t[0]||(t[0]=[s(`<h1 id="异步与消息架构" tabindex="-1">异步与消息架构 <a class="header-anchor" href="#异步与消息架构" aria-label="Permalink to &quot;异步与消息架构&quot;">​</a></h1><blockquote><p>消息队列不是「为了用而用」。它解决的是三个具体问题：<strong>解耦、削峰、最终一致</strong> —— 如果这三个都不沾，就别引入。 Kafka 的存储与副本细节见 <a href="/cao_note/backend/Java/Kafka深入">Kafka 深入</a>，这篇讲<strong>架构层面</strong>怎么用。</p></blockquote><h2 id="一、先判断-该不该异步" tabindex="-1">一、先判断：该不该异步 <a class="header-anchor" href="#一、先判断-该不该异步" aria-label="Permalink to &quot;一、先判断：该不该异步&quot;">​</a></h2><table><thead><tr><th>场景</th><th>该异步吗</th><th>理由</th></tr></thead><tbody><tr><td>发短信、发邮件、推送</td><td>✅</td><td>失败可重试，不影响主流程</td></tr><tr><td>下单后扣积分、写日志、更新报表</td><td>✅</td><td>主流程不需要它的结果</td></tr><tr><td>秒杀削峰</td><td>✅</td><td>用队列把瞬时流量摊平</td></tr><tr><td>查余额</td><td>❌</td><td>必须同步拿到结果</td></tr><tr><td>强一致的扣款</td><td>❌</td><td>异步只会引入不一致</td></tr></tbody></table><p><strong>判断标准一句话</strong>：<strong>调用方需不需要立刻用这个结果</strong>。不需要，就可以异步。</p><h3 id="异步的三种代价" tabindex="-1">异步的三种代价 <a class="header-anchor" href="#异步的三种代价" aria-label="Permalink to &quot;异步的三种代价&quot;">​</a></h3><ol><li><strong>复杂度</strong>：从「一次调用」变成「两个系统 + 一个中间件」，排查链路变长；</li><li><strong>一致性</strong>：从「事务内」变成「最终一致」，必须设计补偿；</li><li><strong>延迟</strong>：正常情况多几十毫秒，异常时可能积压几十分钟。</li></ol><h2 id="二、四种模型" tabindex="-1">二、四种模型 <a class="header-anchor" href="#二、四种模型" aria-label="Permalink to &quot;二、四种模型&quot;">​</a></h2><table><thead><tr><th>模型</th><th>语义</th><th>典型实现</th><th>适用</th></tr></thead><tbody><tr><td><strong>点对点</strong></td><td>一条消息只被一个消费者处理</td><td>RabbitMQ 队列、Kafka 分区</td><td>任务分发</td></tr><tr><td><strong>发布订阅</strong></td><td>一条消息广播给所有订阅者</td><td>Kafka topic + 不同 group、Redis pub/sub</td><td>事件通知</td></tr><tr><td><strong>请求-应答</strong></td><td>异步请求带回复通道</td><td>临时队列 + correlationId</td><td>跨服务调用</td></tr><tr><td><strong>延迟/定时</strong></td><td>到点才投递</td><td>RocketMQ 延迟等级、RabbitMQ DLX+TTL</td><td>订单超时取消</td></tr></tbody></table><h2 id="三、中间件选型-速查" tabindex="-1">三、中间件选型（速查） <a class="header-anchor" href="#三、中间件选型-速查" aria-label="Permalink to &quot;三、中间件选型（速查）&quot;">​</a></h2><table><thead><tr><th></th><th>Kafka</th><th>RocketMQ</th><th>RabbitMQ</th><th>Pulsar</th></tr></thead><tbody><tr><td>定位</td><td>流平台、日志管道</td><td>业务消息</td><td>灵活路由、低延迟</td><td>云原生、存算分离</td></tr><tr><td>吞吐</td><td>极高</td><td>高</td><td>中</td><td>高</td></tr><tr><td>延迟</td><td>ms</td><td>ms</td><td>μs~ms</td><td>ms</td></tr><tr><td>顺序</td><td>分区内</td><td>队列内</td><td>队列内</td><td>分区内</td></tr><tr><td>事务消息</td><td>有（复杂）</td><td><strong>原生</strong></td><td>不支持</td><td>有</td></tr><tr><td>延迟消息</td><td>需外部方案</td><td><strong>原生</strong></td><td>插件/DLX</td><td>支持</td></tr><tr><td>运维</td><td>中</td><td>中</td><td>简单</td><td>复杂</td></tr></tbody></table><p><strong>一句话选型</strong>：日志/埋点/流处理 → Kafka；业务消息 + 事务 + 延迟 → RocketMQ；量不大、路由复杂 → RabbitMQ。</p><h2 id="四、可靠性-还是那三件事" tabindex="-1">四、可靠性：还是那三件事 <a class="header-anchor" href="#四、可靠性-还是那三件事" aria-label="Permalink to &quot;四、可靠性：还是那三件事&quot;">​</a></h2><p>不丢、不重、不乱序 —— 具体配置见 <a href="/cao_note/backend/Java/Kafka深入">Kafka 深入 · 第 6 节</a>，这里只列架构层面的兜底：</p><table><thead><tr><th>问题</th><th>架构层兜底</th></tr></thead><tbody><tr><td><strong>消息丢失</strong></td><td>生产端本地消息表 + 定时补偿；消费端处理成功才 ack</td></tr><tr><td><strong>重复消费</strong></td><td><strong>消费端幂等</strong>（唯一键/去重表/状态机），永远不要指望 MQ 只投一次</td></tr><tr><td><strong>顺序错乱</strong></td><td>同业务 key 打同一分区/队列；消费端串行处理</td></tr></tbody></table><blockquote><p>记住一句：<strong>MQ 只保证「至少一次」，业务必须自己幂等</strong>。</p></blockquote><h2 id="五、事务消息与本地消息表" tabindex="-1">五、事务消息与本地消息表 <a class="header-anchor" href="#五、事务消息与本地消息表" aria-label="Permalink to &quot;五、事务消息与本地消息表&quot;">​</a></h2><p>「本地事务成功，消息一定发出去」—— 这是最容易出问题的地方。</p><h3 id="方案-a-本地消息表-最通用-不依赖-mq-特性" tabindex="-1">方案 A：本地消息表（最通用，不依赖 MQ 特性） <a class="header-anchor" href="#方案-a-本地消息表-最通用-不依赖-mq-特性" aria-label="Permalink to &quot;方案 A：本地消息表（最通用，不依赖 MQ 特性）&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">1. 业务事务里，同时往「消息表」插一条 status=待发送</span></span>
<span class="line"><span style="color:#e1e4e8;">2. 事务提交后，异步任务扫表发送 MQ</span></span>
<span class="line"><span style="color:#e1e4e8;">3. 发送成功 → 状态改「已发送」；失败 → 重试（指数退避）</span></span>
<span class="line"><span style="color:#e1e4e8;">4. 定时任务补偿卡在「待发送」超过 N 分钟的记录</span></span>
<span class="line"><span style="color:#e1e4e8;">5. 消费端幂等（用消息表主键去重）</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">1. 业务事务里，同时往「消息表」插一条 status=待发送</span></span>
<span class="line"><span style="color:#24292e;">2. 事务提交后，异步任务扫表发送 MQ</span></span>
<span class="line"><span style="color:#24292e;">3. 发送成功 → 状态改「已发送」；失败 → 重试（指数退避）</span></span>
<span class="line"><span style="color:#24292e;">4. 定时任务补偿卡在「待发送」超过 N 分钟的记录</span></span>
<span class="line"><span style="color:#24292e;">5. 消费端幂等（用消息表主键去重）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>优点</strong>：任何 MQ 都能用、可靠、易排查。 <strong>缺点</strong>：多一张表、有延迟、扫表要控制频率。</p><h3 id="方案-b-rocketmq-事务消息" tabindex="-1">方案 B：RocketMQ 事务消息 <a class="header-anchor" href="#方案-b-rocketmq-事务消息" aria-label="Permalink to &quot;方案 B：RocketMQ 事务消息&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">1. 发 half message（对消费端不可见）</span></span>
<span class="line"><span style="color:#e1e4e8;">2. 执行本地事务</span></span>
<span class="line"><span style="color:#e1e4e8;">3. 提交/回滚 half message</span></span>
<span class="line"><span style="color:#e1e4e8;">4. 若第 3 步没到达，Broker 回查本地事务状态</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">1. 发 half message（对消费端不可见）</span></span>
<span class="line"><span style="color:#24292e;">2. 执行本地事务</span></span>
<span class="line"><span style="color:#24292e;">3. 提交/回滚 half message</span></span>
<span class="line"><span style="color:#24292e;">4. 若第 3 步没到达，Broker 回查本地事务状态</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>优点</strong>：不用自己扫表。 <strong>缺点</strong>：绑定 RocketMQ，且回查逻辑要幂等。</p><h3 id="方案-c-outbox-cdc-大厂做法" tabindex="-1">方案 C：Outbox + CDC（大厂做法） <a class="header-anchor" href="#方案-c-outbox-cdc-大厂做法" aria-label="Permalink to &quot;方案 C：Outbox + CDC（大厂做法）&quot;">​</a></h3><p>业务表 + outbox 表同库，用 Canal/Debezium 订阅 binlog 投递 MQ。业务代码零侵入，但有运维成本。</p><h2 id="六、延迟消息怎么实现" tabindex="-1">六、延迟消息怎么实现 <a class="header-anchor" href="#六、延迟消息怎么实现" aria-label="Permalink to &quot;六、延迟消息怎么实现&quot;">​</a></h2><table><thead><tr><th>方案</th><th>精度</th><th>说明</th></tr></thead><tbody><tr><td><strong>RocketMQ 延迟等级</strong></td><td>秒级</td><td>开箱即用，等级固定（1s/5s/10s…）</td></tr><tr><td>RabbitMQ DLX + TTL</td><td>秒级</td><td>队列级 TTL 会队头阻塞，不推荐大量使用</td></tr><tr><td>Redis ZSet 轮询</td><td>秒级</td><td><code>score=到期时间</code>，定时任务捞 <code>score &lt;= now</code></td></tr><tr><td><strong>时间轮</strong>（Netty/自研）</td><td>毫秒级</td><td>定时任务框架常用，见 <a href="/cao_note/backend/Java/定时任务调度">定时任务调度</a></td></tr><tr><td>数据库扫表</td><td>分钟级</td><td>订单超时关单最常见的做法</td></tr></tbody></table><p><strong>订单超时取消的推荐组合</strong>：延迟消息（快）+ 定时扫表（兜底，防止消息丢了）。</p><h2 id="七、积压怎么处理" tabindex="-1">七、积压怎么处理 <a class="header-anchor" href="#七、积压怎么处理" aria-label="Permalink to &quot;七、积压怎么处理&quot;">​</a></h2><table><thead><tr><th>情况</th><th>处理</th></tr></thead><tbody><tr><td>消费慢（业务本身耗时）</td><td>扩容消费者（≤ 分区数）、优化单条处理、批量消费</td></tr><tr><td>分区数不够</td><td>扩分区（注意：Kafka 扩分区会打乱 key 的顺序）</td></tr><tr><td>突发流量</td><td>临时把消息转到临时 topic，用更多消费者处理（&quot;搬运&quot;方案）</td></tr><tr><td>消费逻辑阻塞</td><td>加线程池并行处理（但会丢顺序，要按 key 哈希到固定线程）</td></tr></tbody></table><p><strong>先查三件事</strong>：消费者是不是挂了、是不是在反复重试同一条毒消息、下游依赖是不是慢了。</p><h2 id="八、四个常见反模式" tabindex="-1">八、四个常见反模式 <a class="header-anchor" href="#八、四个常见反模式" aria-label="Permalink to &quot;八、四个常见反模式&quot;">​</a></h2><ol><li><strong>用 MQ 做 RPC</strong>（请求-应答、同步等结果）→ 延迟高、失败难处理，直接 HTTP 更好。</li><li><strong>消息体塞整个实体</strong>（几 MB）→ 只发 ID，消费方回查；大消息会拖垮 Broker。</li><li><strong>没有死信队列</strong> → 毒消息无限重试，把整个 topic 堵死。</li><li><strong>消费端不幂等 + 生产端重试</strong> → 重复数据，事后对账一地鸡毛。</li></ol><h2 id="九、速查" tabindex="-1">九、速查 <a class="header-anchor" href="#九、速查" aria-label="Permalink to &quot;九、速查&quot;">​</a></h2><table><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>什么时候该用 MQ</td><td>解耦、削峰、最终一致，三者不沾就别用</td></tr><tr><td>怎么保证不丢</td><td>生产端本地消息表 + 消费端处理成功再 ack</td></tr><tr><td>怎么保证不重</td><td>消费端幂等（唯一键/去重表），别指望 MQ</td></tr><tr><td>怎么保证顺序</td><td>同 key 同分区 + 消费端串行</td></tr><tr><td>事务消息怎么选</td><td>通用选本地消息表；绑 RocketMQ 可用事务消息</td></tr><tr><td>延迟消息怎么做</td><td>RocketMQ 延迟等级 / Redis ZSet / 时间轮，配定时扫表兜底</td></tr><tr><td>积压怎么办</td><td>先查是否卡在毒消息，再扩消费者或扩分区</td></tr><tr><td>最大的坑</td><td>用 MQ 做同步 RPC、消费端不幂等</td></tr></tbody></table>`,36)]))}const g=a(r,[["render",n]]);export{b as __pageData,g as default};
